/* eslint-disable no-restricted-globals */

// This service worker can be customized!
// See https://developer.mozilla.org/en-US/docs/Web/API/Service_Worker

// Precache all of the assets generated by the build process.
// Their URLs are injected into the manifest variable below.
// This variable must be present somewhere in your service worker file,
// even if you decide not to use precaching. See https://cra.link/PWA
const precacheManifest = self.__WB_MANIFEST || [];

// Cache name for storing assets
const CACHE_NAME = 'slay-drip-cache-v2';

// Files to cache - updated for Vite build output
const urlsToCache = [
  '/',
  '/index.html',
  '/favicon.ico',
  '/logo192.png',
  '/logo512.png',
  '/manifest.json'
];

// Install a service worker
self.addEventListener('install', event => {
  // Perform install steps
  event.waitUntil(
    caches.open(CACHE_NAME)
      .then(cache => {
        console.log('Opened cache');
        return cache.addAll(urlsToCache).catch(error => {
          console.error('Failed to cache assets:', error);
          // Cache essential files only if some fail
          return cache.addAll([
            '/',
            '/index.html',
            '/favicon.ico',
            '/manifest.json'
          ]);
        });
      })
  );
});

// Cache and return requests
self.addEventListener('fetch', event => {
  // Only handle GET requests
  if (event.request.method !== 'GET') {
    return;
  }

  // Skip cross-origin requests
  if (!event.request.url.startsWith(self.location.origin)) {
    return;
  }

  event.respondWith(
    caches.match(event.request)
      .then(response => {
        // Cache hit - return response
        if (response) {
          return response;
        }
        
        // For navigation requests, try network first, then fallback to index.html
        if (event.request.mode === 'navigate') {
          return fetch(event.request).catch(() => {
            return caches.match('/index.html');
          });
        }
        
        // For other requests, try network first
        return fetch(event.request).then(response => {
          // Don't cache non-successful responses
          if (!response || response.status !== 200 || response.type !== 'basic') {
            return response;
          }

          // Clone the response as it can only be consumed once
          const responseToCache = response.clone();
          
          caches.open(CACHE_NAME)
            .then(cache => {
              cache.put(event.request, responseToCache);
            });

          return response;
        }).catch(() => {
          // Network failed, return cached response if available
          return caches.match(event.request);
        });
      })
  );
});

// Update a service worker
self.addEventListener('activate', event => {
  const cacheWhitelist = [CACHE_NAME];
  event.waitUntil(
    caches.keys().then(cacheNames => {
      return Promise.all(
        cacheNames.map(cacheName => {
          if (cacheWhitelist.indexOf(cacheName) === -1) {
            return caches.delete(cacheName);
          }
        })
      );
    })
  );
});

// Handle messages from the app
self.addEventListener('message', event => {
  if (event.data && event.data.action === 'CHECK_FOR_UPDATES') {
    // Force check for updates
    self.registration.update();
  }
});
